if __name__=='__main__':
    with (OUT/'references.bib').open('w') as f:
        for r in refs:
            f.write('@'+r['kind']+'{'+r['key']+',\n')
            fields={k:v for k,v in r.items() if k not in ('key','kind','locator','verification')}
            fields['note']='unverified' if r['key'] in {'Cohen1959','HillePhillips1957'} else 'verified'
            fields['annote']=r['locator']+'. '+r['verification']
            for k,v in fields.items():f.write('  '+k+' = {'+v.replace('&','\\&')+'},\n')
            f.write('}\n\n')
    with (OUT/'reference_checks.tsv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=['key','url','locator','verification'],delimiter='\t');w.writeheader()
        w.writerows({k:r[k] for k in w.fieldnames} for r in refs)
